import Link from "@/components/i18n/LocaleLink";
import PageShell from "@/components/public/PageShell";
import Pagination from "@/components/public/Pagination";
import { BreadcrumbJsonLd } from "@/components/public/JsonLd";
import { Breadcrumbs, muted } from "@/components/public/ui";
import { fetchProjects } from "@/lib/api";
import type { Metadata } from "next";
import { toLocale } from "@/lib/i18n/config";
import { getDictionary } from "@/lib/i18n/dictionaries";
import { buildMetadata } from "@/lib/seo";
import { routes } from "@/lib/routes";
import { getProjectsContent } from "./content";

const PER_PAGE = 12;

export async function generateMetadata({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>;
  searchParams: Promise<{ page?: string }>;
}): Promise<Metadata> {
  const locale = toLocale((await params).locale);
  const { common, pages } = getDictionary(locale);
  const page = Math.max(1, Number((await searchParams).page) || 1);
  return buildMetadata({
    locale,
    title: page > 1 ? `${pages.meta.projects} — ${page}` : pages.meta.projects,
    path: "/projects",
    siteName: common.siteShort,
    page,
  });
}

// ISR: список проектов перечитывается из CMS не чаще раза в минуту.
export const revalidate = 60;

// Цвет тега статуса по локале-независимому status_tone из CMS (а НЕ по
// локализованной подписи p.status — иначе на EN/TJ ничего не совпадёт).
const statusChrome: Record<string, { bg: string; fg: string }> = {
  success: { bg: "var(--hz-success-bg)", fg: "var(--hz-success)" },
  info: { bg: "var(--hz-info-bg)", fg: "var(--hz-info)" },
  neutral: { bg: "var(--color-neutral-100)", fg: "var(--color-neutral-800)" },
};

export default async function ProjectsPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>;
  searchParams: Promise<{ page?: string }>;
}) {
  const locale = toLocale((await params).locale);
  const c = getProjectsContent(locale);
  const { pages } = getDictionary(locale);
  const page = Math.max(1, Number((await searchParams).page) || 1);
  const { data: projects, meta } = await fetchProjects({ locale, page, perPage: PER_PAGE });

  return (
    <PageShell
      active=""
      locale={locale}
      mainClassName="mx-auto w-full max-w-[1160px] px-6 pt-8 max-[920px]:px-4"
    >
      <BreadcrumbJsonLd items={c.breadcrumbs} locale={locale} />
      <Breadcrumbs items={c.breadcrumbs} />

      {/* Заголовок раздела */}
      <div className="border-b border-[var(--color-divider)] pb-[14px]">
        <h1 className="m-0 mb-2 text-[36px] uppercase tracking-[.02em]">
          {c.title}
        </h1>
        <p
          className="m-0 max-w-[70ch] text-[14.5px] leading-[1.6]"
          style={{ color: muted(70) }}
        >
          {c.intro}
        </p>
      </div>

      {/* Карточки проектов */}
      {projects.length > 0 ? (
        <div className="mt-6 grid grid-cols-2 gap-[14px] max-[920px]:grid-cols-1">
          {projects.map((p, i) => {
            const sc = statusChrome[p.status_tone] ?? statusChrome.neutral;
            return (
              <Link
                key={p.slug}
                href={routes.project(p.slug)}
                className="blueprint surface-hover flex min-w-0 flex-col gap-2.5 p-[22px]"
                style={{ textDecoration: "none", color: "inherit" }}
              >
                <div className="flex flex-wrap items-center gap-2">
                  <span
                    className="text-[13px] font-semibold [font-family:var(--font-heading)]"
                    style={{ color: muted(40) }}
                  >
                    {String(i + 1).padStart(2, "0")}
                  </span>
                  <span
                    className="tag font-semibold"
                    style={{ background: sc.bg, color: sc.fg }}
                  >
                    {p.status}
                  </span>
                  {p.years && <span className="tag tag-neutral">{p.years}</span>}
                </div>
                <span className="text-[21px] font-semibold leading-[1.2] [font-family:var(--font-heading)]">
                  {p.title}
                </span>
                <span
                  className="text-[13.5px] leading-[1.55]"
                  style={{ color: muted(65) }}
                >
                  {p.desc}
                </span>
                <div
                  className="mt-auto flex flex-wrap gap-5 border-t border-[var(--color-divider)] pt-2.5 text-xs"
                  style={{ color: muted(58) }}
                >
                  {p.partner && (
                    <span>
                      <strong style={{ color: "var(--color-text)" }}>
                        {c.cardLabels.partner}
                      </strong>{" "}
                      {p.partner}
                    </span>
                  )}
                  {p.budget && (
                    <span>
                      <strong style={{ color: "var(--color-text)" }}>
                        {c.cardLabels.budget}
                      </strong>{" "}
                      {p.budget}
                    </span>
                  )}
                </div>
              </Link>
            );
          })}
        </div>
      ) : (
        <p className="mt-6 text-[14px]" style={{ color: muted(60) }}>
          {pages.projectsList.empty}
        </p>
      )}

      <Pagination
        locale={locale}
        currentPage={meta.current_page}
        lastPage={meta.last_page}
        basePath="/projects"
      />

      {/* Связанные разделы */}
      <section
        aria-label={c.related.aria}
        className="blueprint mt-8 flex flex-wrap items-center gap-6 px-5 py-[18px]"
      >
        <p
          className="m-0 min-w-[260px] flex-1 text-[13.5px] leading-[1.55]"
          style={{ color: muted(70) }}
        >
          {c.related.text}
        </p>
        <Link href={routes.announcements} className="btn btn-secondary">
          {c.related.tenders}
        </Link>
        <Link href={routes.documents} className="btn btn-ghost">
          {c.related.reports}
        </Link>
      </section>
    </PageShell>
  );
}
